class StringIterator {
public:
    string res;
    int ptr = 0, num = 0;
    char ch = ' ';

    StringIterator(string compressedString) {
        res = compressedString;
    }

    char next() {
        if (!hasNext())
            return ' ';

        if (num == 0) {
            ch = res[ptr++];
            while (ptr < res.length() && isdigit(res[ptr])) {
                num = num * 10 + (res[ptr++] - '0');
            }
        }

        num--;
        return ch;
    }

    bool hasNext() {
        return ptr != res.length() || num != 0;
    }
};
